insert into practice_context_blocks (id, exercise_id, label, image_url, text_content, block_type) values
  ('c20d4dbc-b7df-4574-bcfd-b9c8e36e7450', '8b90e5f9-c614-497e-8860-c4145df041f1', $$inleiding: rivierdonderpadden in de Leidse grachten$$,
   $$biologie-havo-2023-i-rivierdonderpad-in-de-leidse-grachten-context1.png$$,
   $$Aaf Verkade is adviseur stadsgrachten en leidt het project vismonitoring in Leiden. Tijdens een schoonmaakbeurt van de Leidse grachten trof ze rivierdonderpadden aan in de opgeviste rommel.$$, 'inline'),
  ('3b2ff534-5f73-4b5e-bb7d-f2af8d059b84', '8b90e5f9-c614-497e-8860-c4145df041f1', $$de rivierdonderpad als bodemvis (afbeelding 1)$$,
   $$biologie-havo-2023-i-rivierdonderpad-in-de-leidse-grachten-context2.png$$,
   $$De rivierdonderpad (Cottus perifretum, afbeelding 1) is een inheemse bodemvis die ''s nachts jaagt op vlo-kreeften, waterpissebedden en muggenlarven. De rivierdonderpad wordt gemiddeld 13 cm lang. Overdag verschuilt de vis zich tussen stenen of boomwortels voor predatoren zoals rivierkreeften.
afbeelding 1: foto van een rivierdonderpad op de bodem tussen stenen$$, 'inline'),
  ('2bcf22b9-0353-481f-9323-1c669fc12849', '8b90e5f9-c614-497e-8860-c4145df041f1', $$schoonmaakbeurt verstoort de leefomgeving$$,
   $$biologie-havo-2023-i-rivierdonderpad-in-de-leidse-grachten-context3.png$$,
   $$Door de schoonmaakbeurt van de Leidse grachten wordt de leefomgeving van de rivierdonderpad ernstig verstoord. Met het verwijderen van rommel zoals winkelwagentjes en visnetten, verdwijnen ook schuilplaatsen voor de rivierdonderpad.$$, 'inline'),
  ('78a95528-f551-4464-b861-8022c46b1037', '8b90e5f9-c614-497e-8860-c4145df041f1', $$rivierdonderpaddenhotels als extra schuilplek$$,
   $$biologie-havo-2023-i-rivierdonderpad-in-de-leidse-grachten-context4.png$$,
   $$Om de rivierdonderpadden te helpen, bedacht Verkade rivierdonderpaddenhotels. Dat zijn houten kisten (afbeelding 2) die in de grachten geplaatst kunnen worden. Zo krijgen de rivierdonderpadden extra schuilplekken.$$, 'inline'),
  ('91ca345c-e5a5-4bab-8ff8-0099f6990fef', '8b90e5f9-c614-497e-8860-c4145df041f1', $$afbeelding 2: rivierdonderpaddenhotel$$,
   $$biologie-havo-2023-i-rivierdonderpad-in-de-leidse-grachten-context5.png$$,
   $$afbeelding 2: foto van een rivierdonderpaddenhotel onder water en een tekening van de houten kist (30 cm × 20 cm × 25 cm) met smalle spleten in de wanden$$, 'inline'),
  ('528f1bf1-fc4b-4d98-981c-9857e8672c0b', '8b90e5f9-c614-497e-8860-c4145df041f1', $$spleten beïnvloeden biotische en abiotische factoren$$,
   $$biologie-havo-2023-i-rivierdonderpad-in-de-leidse-grachten-context6.png$$,
   $$De rivierdonderpadden kunnen via smalle spleten in het hotel kruipen. Het aantal spleten en de grootte ervan, beïnvloeden ook de biotische en abiotische factoren voor de rivierdonderpadden in het hotel.$$, 'inline'),
  ('e40db4dd-3aca-433a-814f-ebb2245280ca', '8b90e5f9-c614-497e-8860-c4145df041f1', $$zwartbekgrondel als bedreiging; voorstel om een predator te introduceren$$,
   $$biologie-havo-2023-i-rivierdonderpad-in-de-leidse-grachten-context7.png$$,
   $$Tijdens een excursie langs de gracht vertelt Verkade over de bedreigingen voor de rivierdonderpad: “Het verdwijnen van schuilplekken is niet de enige bedreiging voor de rivierdonderpad. In Nederland worden de laatste jaren ook zwartbekgrondels (Neogobius melanostomus) waargenomen. Deze vissen komen oorspronkelijk uit gebieden rond de Zwarte Zee en de Kaspische Zee. Ze hebben dezelfde levenswijze als de rivierdonderpad.” Een deelnemer stelt voor om een predator uit de oorspronkelijke leefomgeving van de zwartbekgrondel te introduceren.$$, 'inline'),
  ('03544714-c186-4a68-b0b9-f0399fe7ae07', '2b7aec8b-d2f2-49cc-afae-56ef7a1e444e', $$inleiding: voedselbos Ketelbroek$$,
   $$biologie-havo-2023-i-een-bos-om-op-te-eten-context1.png$$,
   $$In 2009 kocht Wouter van Eck een akker waarop jarenlang mais was verbouwd. Hij heeft er voedselbos Ketelbroek aangelegd, een combinatie van landbouw en natuur (afbeelding 1).$$, 'inline'),
  ('1997bd12-f83a-45aa-89e3-b9b3d15ec86b', '2b7aec8b-d2f2-49cc-afae-56ef7a1e444e', $$afbeelding 1: luchtfoto van het voedselbos$$,
   $$biologie-havo-2023-i-een-bos-om-op-te-eten-context2.png$$,
   $$afbeelding 1: luchtfoto van voedselbos Ketelbroek tussen omringende akkers$$, 'inline'),
  ('7705085c-4998-4763-9817-dc1739f3f0d4', '2b7aec8b-d2f2-49cc-afae-56ef7a1e444e', $$meer dan 350 plantensoorten, geen mest of bestrijdingsmiddelen$$,
   $$biologie-havo-2023-i-een-bos-om-op-te-eten-context3.png$$,
   $$In het voedselbos staan meer dan 350 verschillende plantensoorten, die allemaal iets eetbaars opleveren: notenbomen, tamme kastanjes, kiwi’s, bessenstruiken en kruiden als daslook en tijm. Na het planten heeft Wouter het gebied met rust gelaten: hij ploegt niet, gebruikt geen mest en geen chemische bestrijdingsmiddelen. Hij snoeit en oogst alleen maar.$$, 'inline'),
  ('7fb51db2-177e-4ebf-ab49-3c591ca0e589', '2b7aec8b-d2f2-49cc-afae-56ef7a1e444e', $$monocultuur van aardappelen rondom het voedselbos$$,
   $$biologie-havo-2023-i-een-bos-om-op-te-eten-context4.png$$,
   $$Op de akkers rondom het voedselbos worden alleen aardappelen verbouwd. Zo’n monocultuur is gevoeliger voor plagen dan een voedselbos.$$, 'inline'),
  ('c634caa2-e23c-4a15-a400-b891f4b05503', '2b7aec8b-d2f2-49cc-afae-56ef7a1e444e', $$luchtige, niet-verstoorde bodem$$,
   $$biologie-havo-2023-i-een-bos-om-op-te-eten-context5.png$$,
   $$Wouter rijdt niet met machines door zijn bos. Zo wordt het bodemleven niet verstoord en blijft de bodem luchtig.$$, 'inline'),
  ('1483ff56-3d3a-418d-b98f-cdc8f28b85f9', '2b7aec8b-d2f2-49cc-afae-56ef7a1e444e', $$bodemschimmels in plantenwortels$$,
   $$biologie-havo-2023-i-een-bos-om-op-te-eten-context6.png$$,
   $$In een niet-verstoorde bodem vormen bodemschimmels uitgebreide netwerken van schimmeldraden. De schimmels dringen de wortels van planten binnen om daar organische stoffen op te nemen. De schimmeldraden nemen anorganische stoffen uit de bodem op, die vervolgens ook gebruikt worden door de plant.$$, 'inline'),
  ('18517405-c188-47f3-bf17-c7dda14f8850', '2b7aec8b-d2f2-49cc-afae-56ef7a1e444e', $$omzetting van organische stikstofverbindingen naar nitraat; groepen bodembacteriën$$,
   $$biologie-havo-2023-i-een-bos-om-op-te-eten-context7.png$$,
   $$Wouter gebruikt geen kunstmest of compost in zijn voedselbos. Bladeren die van de bomen vallen en kruidachtige planten die afsterven, voegen voldoende organische stof toe aan de bodem. De organische stikstofverbindingen worden in verschillende stappen door bodembacteriën omgezet naar nitraat (NO₃⁻). Groepen bodembacteriën zijn:
1 denitrificerende bacteriën
2 nitraatbacteriën
3 nitrietbacteriën
4 rottingsbacteriën$$, 'inline'),
  ('01578d27-d238-49b0-a9ca-2f6e46338747', '2b7aec8b-d2f2-49cc-afae-56ef7a1e444e', $$olijfwilgen met wortelknolletjes en stikstofbindende bacteriën$$,
   $$biologie-havo-2023-i-een-bos-om-op-te-eten-context8.png$$,
   $$Wouter heeft een aantal olijfwilgen aangeplant in het voedselbos. Deze struiken met eetbare rode bessen bezitten wortelknolletjes waarin bacteriën leven. De bacteriën binden stikstof (N₂) uit de lucht, waardoor een stof ontstaat die de planten kunnen gebruiken voor het maken van organische stikstofverbindingen. In afbeelding 2 is dit proces schematisch weergegeven.$$, 'inline'),
  ('cba936bd-20b5-448f-882d-d18bca1f7362', '2b7aec8b-d2f2-49cc-afae-56ef7a1e444e', $$afbeelding 2: schema stikstofbinding in bacterie en olijfwilg$$,
   $$biologie-havo-2023-i-een-bos-om-op-te-eten-context9.png$$,
   $$afbeelding 2: schema met LUCHT, BACTERIE en OLIJFWILG: N₂ uit de lucht → proces 1 → stof 2 (in de bacterie) → proces 3 → stof 4 (in de olijfwilg)$$, 'inline'),
  ('27aca95d-1bdd-4d36-9306-a3bb62cb8341', '2b7aec8b-d2f2-49cc-afae-56ef7a1e444e', $$stoffen en processen voor afbeelding 2$$,
   $$biologie-havo-2023-i-een-bos-om-op-te-eten-context10.png$$,
   $$In afbeelding 2 moeten op de plaats van de nummers de volgende stoffen en processen ingevuld worden:
− aminozuur
− NH₃
− stikstofassimilatie
− stikstoffixatie$$, 'inline'),
  ('e31f91e0-c2e5-492c-a45b-a5439fdce3f4', '2b7aec8b-d2f2-49cc-afae-56ef7a1e444e', $$daslook en tijm: schaduw en zon$$,
   $$biologie-havo-2023-i-een-bos-om-op-te-eten-context11.png$$,
   $$De abiotische factoren in het voedselbos variëren sterk van plaats tot plaats. Daslook (afbeelding 3), met blaadjes die naar knoflook smaken, groeit goed op schaduwrijke plaatsen. Tijm (afbeelding 4), een kruid dat in veel gerechten wordt gebruikt, groeit alleen op zonnige open plaatsen.$$, 'inline'),
  ('40b20dcd-b5f2-427c-a6da-b467a211b51d', '2b7aec8b-d2f2-49cc-afae-56ef7a1e444e', $$afbeelding 3 en 4: daslook en tijm$$,
   $$biologie-havo-2023-i-een-bos-om-op-te-eten-context12.png$$,
   $$afbeelding 3: foto van bloeiende daslook
afbeelding 4: foto van bloeiende tijm$$, 'inline'),
  ('ebc071e6-3cb3-4d5e-8ae7-fce1f484d8ff', '2b7aec8b-d2f2-49cc-afae-56ef7a1e444e', $$optimumkrommes voor lichtsterkte$$,
   $$biologie-havo-2023-i-een-bos-om-op-te-eten-context13.png$$,
   $$De optimumkrommes voor lichtsterkte van daslook en tijm worden vergeleken.$$, 'inline'),
  ('9f61e8a0-ee06-4a5a-90b3-352198355f4d', '2b7aec8b-d2f2-49cc-afae-56ef7a1e444e', $$bladeren van schaduwplanten$$,
   $$biologie-havo-2023-i-een-bos-om-op-te-eten-context14.png$$,
   $$Schaduwplanten hebben meestal grotere, dunnere bladeren met een dunnere cuticula (waslaag) dan planten die in de volle zon groeien.$$, 'inline'),
  ('cfcc464e-cb53-45d2-9824-570fc259ed7c', '2b7aec8b-d2f2-49cc-afae-56ef7a1e444e', $$geïmporteerde plantensoorten$$,
   $$biologie-havo-2023-i-een-bos-om-op-te-eten-context15.png$$,
   $$In Ketelbroek staan ook bomen en struiken uit andere delen van de wereld, zoals de Sichuan-peperboom uit China, de Siberische honingbes en de Koreaanse pijnboom. Soms kunnen geïmporteerde plantensoorten zich vestigen in Nederlandse ecosystemen.$$, 'inline'),
  ('f2131469-1970-4f8c-bdd8-a73fdf8518f4', '2b7aec8b-d2f2-49cc-afae-56ef7a1e444e', $$voedselbos en het versterkt broeikaseffect$$,
   $$biologie-havo-2023-i-een-bos-om-op-te-eten-context16.png$$,
   $$Ketelbroek is nog lang niet uitgegroeid. De totale massa aan bomen en struiken zal nog flink groter worden. In tegenstelling tot een maisakker kan het voedselbos daardoor bijdragen aan het terugdringen van het versterkt broeikaseffect.$$, 'inline'),
  ('7d45931f-4e5b-406c-a570-4a312a9f25ec', 'a65f396c-9aea-4a58-b2ee-fc655bbae7c2', $$inleiding: verloskundige Layla begeleidt Monique$$,
   $$biologie-havo-2023-i-spoedkeizersnede-context1.png$$,
   $$Layla is verloskundige. Ze begeleidt de zwangere Monique vanaf de prille zwangerschap tot en met de bevalling.$$, 'inline'),
  ('16e492e0-e339-4c9a-94d9-a72ec410c9ba', 'a65f396c-9aea-4a58-b2ee-fc655bbae7c2', $$HCG in zwangerschapstest; zes bloedvaten$$,
   $$biologie-havo-2023-i-spoedkeizersnede-context2.png$$,
   $$Monique kocht een zwangerschapstest bij de drogist nadat haar menstruatie uitbleef. Zo’n test toont het hormoon HCG in de urine aan. Het embryonaal deel van de placenta produceert gedurende het begin van de zwangerschap steeds meer HCG, dat in het bloed van de moeder terechtkomt. Enkele bloedvaten zijn:
1 longader
2 longslagader
3 nierader
4 nierslagader
5 ader van de baarmoeder
6 slagader van de baarmoeder$$, 'inline'),
  ('82bdefb6-06b8-48d3-a556-d4b754f854c6', 'a65f396c-9aea-4a58-b2ee-fc655bbae7c2', $$afwijkende bloeddruk door vernauwde slagadertjes$$,
   $$biologie-havo-2023-i-spoedkeizersnede-context3.png$$,
   $$Bij elk bezoek controleert Layla Moniques bloeddruk. Bij sommige zwangere vrouwen komt namelijk een afwijkende bloeddruk voor die ongunstig kan zijn voor de foetus. De afwijkende bloeddruk ontstaat doordat stoffen uit de placenta de slagadertjes in het lichaam van de moeder laten vernauwen.$$, 'inline'),
  ('d0724408-f211-43aa-9668-ba898f316e56', 'a65f396c-9aea-4a58-b2ee-fc655bbae7c2', $$zuchten (buikademhaling) en puffen (borstademhaling) bij weeën$$,
   $$biologie-havo-2023-i-spoedkeizersnede-context4.png$$,
   $$Layla legt uit aan Monique hoe ze de weeën (samentrekkingen van de baarmoederwand) tijdens de bevalling zo goed mogelijk kan opvangen: “In het begin is zuchten (rustige buikademhaling) gunstig voor de voortgang van de bevalling. Wanneer een wee te heftig wordt, kan je overgaan op puffen (snelle borstademhaling) zodat er nog niet te veel druk op de baarmoeder gezet wordt.”$$, 'inline'),
  ('222b2734-26cd-49a9-88ef-68806f6dab56', 'a65f396c-9aea-4a58-b2ee-fc655bbae7c2', $$kader: cardiotocograaf en CTG (afbeelding 1 en 2)$$,
   $$biologie-havo-2023-i-spoedkeizersnede-context5.png$$,
   $$Layla wordt gebeld als de weeën bij Monique zijn begonnen. Als na een paar uur de bevalling niet snel genoeg vordert, stuurt Layla Monique naar het ziekenhuis. Daar draagt Layla de bevalling over aan de gynaecoloog. De gynaecoloog legt twee banden met meetapparatuur om Moniques buik om via een cardiotocograaf de hartactiviteit van de baby en de weeënactiviteit van de baarmoeder te registreren (afbeelding 1). De registratie is te zien op een monitor en wordt geprint op een rol papier: het cardiotocogram (CTG). In afbeelding 2 is een deel van een CTG afgebeeld. Aan de bovenste lijn is te zien dat de hartslagfrequentie van de baby ligt tussen 110 en 150 slagen per minuut. De onderste lijn geeft de druk op de buikwand weer, die tijdens een wee ongeveer verdubbeld is.
afbeelding 1: foto van een zwangere vrouw met twee banden met meetapparatuur om haar buik, naast een cardiotocograaf
afbeelding 2: deel van een CTG; bovenste lijn: hartslagfrequentie van de baby (schaal 60-180), onderste lijn: druk op de buikwand (schaal 20-100); een schaalstreepje geeft 1 minuut aan$$, 'inline'),
  ('ef0cda86-f502-4263-b096-ea6fb9966f3c', 'a65f396c-9aea-4a58-b2ee-fc655bbae7c2', $$aantal weeën per 10 minuten$$,
   $$biologie-havo-2023-i-spoedkeizersnede-context6.png$$,
   $$De frequentie waarmee weeën optreden, kan worden uitgedrukt in het aantal weeën per 10 minuten.$$, 'inline'),
  ('62ac7547-411b-4795-bc0a-8072dcce8b70', 'a65f396c-9aea-4a58-b2ee-fc655bbae7c2', $$normale hartslagfrequentie van de ongeboren baby$$,
   $$biologie-havo-2023-i-spoedkeizersnede-context7.png$$,
   $$De hartslagfrequentie van een ongeboren baby ligt normaal tussen 110 en 150 slagen per minuut. De gynaecoloog leest het CTG regelmatig af. Ze let daarbij onder andere op versnellingen en vertragingen van de hartslagfrequentie in combinatie met de weeënactiviteit.$$, 'inline'),
  ('f641da38-99b4-48a4-9e48-4114f9792a9a', 'a65f396c-9aea-4a58-b2ee-fc655bbae7c2', $$drie situaties af te leiden uit een CTG$$,
   $$biologie-havo-2023-i-spoedkeizersnede-context8.png$$,
   $$Aan de hand van het CTG kan de gynaecoloog bepalen hoe het met de baby gaat. Drie situaties die kunnen worden afgeleid uit een CTG zijn:
1 De baby reageert op een wee met een verhoogde afgifte van noradrenaline.
2 Tijdens een wee is de activiteit van het parasympatisch zenuwstelsel van de baby verhoogd.
3 De bloedstroom naar de baby is langer dan drie minuten ernstig verstoord.$$, 'inline'),
  ('1f576b57-a4f8-4965-abdc-768f3482c4fd', 'a65f396c-9aea-4a58-b2ee-fc655bbae7c2', $$drie delen van CTG's: P, Q en R$$,
   $$biologie-havo-2023-i-spoedkeizersnede-context9.png$$,
   $$In afbeelding 3 zijn drie delen van CTG’s aangegeven met P, Q en R.$$, 'inline'),
  ('bb3550a6-cc52-40a3-b93a-d267894e2ce4', 'a65f396c-9aea-4a58-b2ee-fc655bbae7c2', $$afbeelding 3: CTG-delen P, Q en R$$,
   $$biologie-havo-2023-i-spoedkeizersnede-context10.png$$,
   $$afbeelding 3: drie delen van CTG''s (deel P, deel Q en deel R), elk met bovenaan de hartslagfrequentie van de baby (schaal 60-180) en onderaan de druk op de buikwand (schaal 20-100); legenda: schaalstreepje = 1 minuut$$, 'inline'),
  ('9e78e576-46cd-4a5e-a3e2-2cb367b8b35b', 'a65f396c-9aea-4a58-b2ee-fc655bbae7c2', $$kader: pH-bepaling van bloed uit de hoofdhuid van de baby$$,
   $$biologie-havo-2023-i-spoedkeizersnede-context11.png$$,
   $$Het CTG van Monique wijst erop dat de bloedstroom naar haar baby verstoord is. De gynaecoloog voert daarom een bloedonderzoek uit. Via de vagina van Monique neemt zij een druppeltje bloed af uit de hoofdhuid van de baby. Hiervan wordt de pH bepaald. Wanneer de pH van dit bloed lager is dan 7,2 moet de baby snel geboren worden.$$, 'inline'),
  ('dff0da72-b95f-4efb-81b4-e9840f938a03', 'a65f396c-9aea-4a58-b2ee-fc655bbae7c2', $$lage pH door hoge CO₂-concentratie$$,
   $$biologie-havo-2023-i-spoedkeizersnede-context12.png$$,
   $$Een lage pH van bloed wijst op zuurstofgebrek. Een lage pH wordt namelijk veroorzaakt door een veel te hoge CO₂-concentratie in het bloed.$$, 'inline'),
  ('e0cd3cfb-f980-4303-b5c1-bed32a175b5b', 'a65f396c-9aea-4a58-b2ee-fc655bbae7c2', $$ruggenprik blokkeert impulsgeleiding$$,
   $$biologie-havo-2023-i-spoedkeizersnede-context13.png$$,
   $$De pH van het bloed van de baby is 7,1. Omdat de bevalling niet vordert, besluit de gynaecoloog in overleg met Monique tot een keizersnede. Monique krijgt eerst een ruggenprik. Hierbij wordt een verdovend middel gespoten in het vocht rondom het ruggenmerg. Dit middel blokkeert daar de impulsgeleiding over de uitlopers van bepaalde cellen van het perifeer zenuwstelsel. Pijn in het onderlichaam wordt hierdoor niet door de hersenen waargenomen.$$, 'inline'),
  ('a3d19cf3-497f-457d-977f-50a7d3f26dce', 'a65f396c-9aea-4a58-b2ee-fc655bbae7c2', $$beschrijving van de keizersnede met weggelaten woorden (afbeelding 4)$$,
   $$biologie-havo-2023-i-spoedkeizersnede-context14.png$$,
   $$Hieronder is een beschrijving van de operatie weergegeven. Op vier plaatsen zijn een aantal woorden weggelaten.
De gynaecoloog maakt een horizontale snede vlak boven het schaambeen (afbeelding 4). Na de snede door …(1)… wordt …(2)… doorgesneden. Door …(3)… opzij te duwen opent ze de buikholte. Vervolgens wordt …(4)… naar beneden geschoven. Daarna maakt ze een dwarse snede in de baarmoeder en haalt ze de baby eruit.
De woorden die in de beschrijving zijn weggelaten zijn:
− de blaas
− de huid
− de laag vet- en bindweefsel
− het buikspierweefsel
afbeelding 4: lengtedoorsnede van de buik van een zwangere vrouw met de baby in de baarmoeder; het schaambeen is aangegeven$$, 'inline'),
  ('f13a349b-7c0b-4ae6-886b-034eca440495', 'a65f396c-9aea-4a58-b2ee-fc655bbae7c2', $$hormoon dat de baarmoeder laat samentrekken$$,
   $$biologie-havo-2023-i-spoedkeizersnede-context15.png$$,
   $$Nadat de baby is geboren, wordt de navelstreng doorgeknipt. Monique krijgt een hormoon toegediend om de baarmoeder te laten samentrekken, waardoor overmatig bloedverlies wordt voorkomen. Dit is hetzelfde hormoon dat aan het begin van de bevalling de weeën opwekte.$$, 'inline'),
  ('103b3db6-91a9-4a32-a984-bb5f744fd3c0', 'a65f396c-9aea-4a58-b2ee-fc655bbae7c2', $$controle van de baby, waaronder de pupilreflex$$,
   $$biologie-havo-2023-i-spoedkeizersnede-context16.png$$,
   $$Monique kijkt mee hoe haar baby gecontroleerd wordt. De kleur, hartslag, ademhaling en spierspanning zijn goed. Ook de reflexen zoals de pupilreflex zijn in orde.$$, 'inline'),
  ('b147e9fb-f8b5-4fd2-86af-0471a7afe293', '935621eb-74ff-4a67-bbc5-9b028f2d79d4', $$inleiding: planten reageren op geluid van bestuivers$$,
   $$biologie-havo-2023-i-planten-horen-bijen-vliegen-context1.png$$,
   $$Onderzoekers hebben ontdekt dat planten kunnen reageren op het geluid van passerende bestuivers.$$, 'inline'),
  ('67efd903-e857-4992-8a0b-c1db4c5c796b', '935621eb-74ff-4a67-bbc5-9b028f2d79d4', $$kader: teunisbloemen produceren zoetere nectar (afbeelding 1)$$,
   $$biologie-havo-2023-i-planten-horen-bijen-vliegen-context2.png$$,
   $$De onderzoekers lieten teunisbloemen (afbeelding 1) het geluid van een vliegende honingbij ''horen''. De bloemen bleken in reactie daarop veel zoetere nectar te gaan produceren. Volgens de onderzoekers functioneren de bloemen van de plant als gehoororgaan. "We ontdekten dat de bloemen door deze geluiden gingen trillen", zo schrijven de onderzoekers. Wat hun verder opviel, is dat de bloemen wel reageerden op de geluiden van bestuivers, maar niet op geluiden met een hogere frequentie.
afbeelding 1: foto van teunisbloemen; de bloembeker is aangegeven$$, 'inline'),
  ('7748a9e2-d5f4-4f0f-964b-98b5e7319513', '935621eb-74ff-4a67-bbc5-9b028f2d79d4', $$nectarklieren in de bloembeker$$,
   $$biologie-havo-2023-i-planten-horen-bijen-vliegen-context3.png$$,
   $$Nectar wordt gemaakt door klieren in de bloembeker en bevat een hoge concentratie aan suikers.$$, 'inline'),
  ('2f45fe13-131c-4e2b-9635-4c421f00aefc', '935621eb-74ff-4a67-bbc5-9b028f2d79d4', $$zelfbestuiving en kruisbestuiving$$,
   $$biologie-havo-2023-i-planten-horen-bijen-vliegen-context4.png$$,
   $$Teunisbloemen zijn in staat tot zelfbestuiving. Door meer bestuivers te lokken, wordt de kans op kruisbestuiving (met stuifmeel van een andere teunisbloem-plant) groter.$$, 'inline'),
  ('bd409825-4279-430c-957d-ede94b52b140', '935621eb-74ff-4a67-bbc5-9b028f2d79d4', $$aankondiging van het fragment uit de publicatie$$,
   $$biologie-havo-2023-i-planten-horen-bijen-vliegen-context5.png$$,
   $$De onderzoekers schreven het volgende in hun publicatie:$$, 'inline'),
  ('5b19b33a-6477-4fd7-8fe8-3082fe69efc2', '935621eb-74ff-4a67-bbc5-9b028f2d79d4', $$fragment uit de publicatie (regel 1-15)$$,
   $$biologie-havo-2023-i-planten-horen-bijen-vliegen-context6.png$$,
   $$1 Kunnen planten geluidsgolven waarnemen en daarop reageren?
2 Als dat zo is, zou een plant meer bestuivers kunnen lokken.
3 Stel dat planten de geluidsgolven van honingbijen kunnen opvangen
4 en dan hun nectar aantrekkelijker kunnen maken, dan verwachten we
5 dat de bloem zal gaan trillen en zoetere nectar zal produceren na
6 blootstelling aan het geluid van een vliegende honingbij.
7 We gebruikten teunisbloemen (Oenothera drummondii), waarvan de
8 honingbij de voornaamste bestuiver is.
9 We maten de trillingen van de bloembladeren en de suikerconcentratie
10 in de nectar in reactie op geluidsopnames van bestuivers en
11 synthetische geluiden van verschillende frequenties.
12 Wat blijkt: zowel het geluid van bestuivers als een synthetisch geluid
13 met een overeenkomstige frequentie veroorzaakt trillingen in de
14 bloembladeren die leiden tot een snelle toename in de
15 suikerconcentratie van de nectar.$$, 'inline'),
  ('09ae9eb4-fba9-4e8a-8bae-6d6b8e47e254', '935621eb-74ff-4a67-bbc5-9b028f2d79d4', $$suikerconcentratie (brix-waarde) van nectar na verschillende geluiden$$,
   $$biologie-havo-2023-i-planten-horen-bijen-vliegen-context7.png$$,
   $$In afbeelding 2 is de suikerconcentratie weergegeven van de nectar na stilte, na een hoog geluid, na een laag geluid (met dezelfde frequentie als het geluid van honingbijen) en na het afspelen van een geluidsopname van een echte honingbij. De suikerconcentratie is uitgedrukt in de brix-waarde. Hoe hoger deze waarde, hoe hoger de suikerconcentratie.$$, 'inline'),
  ('6912457b-628a-4cfc-9268-69bbb1cf7add', '935621eb-74ff-4a67-bbc5-9b028f2d79d4', $$afbeelding 2: brix-waarde na stilte, hoog, laag en honingbij-geluid$$,
   $$biologie-havo-2023-i-planten-horen-bijen-vliegen-context8.png$$,
   $$afbeelding 2: staafdiagram van de brix-waarde (y-as 15-20, met asonderbreking vanaf 0): stilte ongeveer 16,5; hoog geluid ongeveer 16,0; laag geluid ongeveer 19,6; honingbij-geluid ongeveer 19,1$$, 'inline'),
  ('7574aa19-d42a-466a-8b23-fdb70f713bcf', '935621eb-74ff-4a67-bbc5-9b028f2d79d4', $$honingbijen nemen een toename van de brix-waarde van meer dan 3% waar$$,
   $$biologie-havo-2023-i-planten-horen-bijen-vliegen-context9.png$$,
   $$Doordat bijen verschil in suikerconcentratie kunnen waarnemen, zullen ze met name bloemen gaan bezoeken die nectar met een hoge suikerconcentratie produceren. Als de brix-waarde meer dan 3% toeneemt, kunnen honingbijen dit waarnemen.$$, 'inline'),
  ('9ea90bcd-77bb-40a3-97d4-aaf47b86d078', '935621eb-74ff-4a67-bbc5-9b028f2d79d4', $$teunisbloemen reageren niet op hogere frequenties$$,
   $$biologie-havo-2023-i-planten-horen-bijen-vliegen-context10.png$$,
   $$Wat opvalt, is dat de planten niet op alle trillingen reageren. Teunisbloemen produceren wel zoetere nectar na het waarnemen van de geluidsfrequentie van hun bestuivers, maar reageren niet of nauwelijks op geluiden met een hogere frequentie.$$, 'inline'),
  ('1313c740-3881-41fd-84da-6941272f2817', '8c168e5b-33a0-4aba-b57a-183148ef9ca1', $$inleiding: Ryan groeit onvoldoende en ziet bleek$$,
   $$biologie-havo-2023-i-beta-thalassemie-genezen-met-stamceltransplantatie-context1.png$$,
   $$Bij zijn geboorte leek Ryan gezond. Als het jongetje een half jaar oud is, blijkt hij echter onvoldoende gegroeid te zijn en ziet hij erg bleek.$$, 'inline'),
  ('859a7d3a-9614-42f1-ae12-1b27c26c6305', '8c168e5b-33a0-4aba-b57a-183148ef9ca1', $$kader: bèta-thalassemie en de ontwikkeling van stamcel tot erytrocyt (afbeelding 1)$$,
   $$biologie-havo-2023-i-beta-thalassemie-genezen-met-stamceltransplantatie-context2.png$$,
   $$Na bloedonderzoek blijkt Ryan de ziekte bèta-thalassemie te hebben, een erfelijke ziekte als gevolg van een mutatie in een gen voor hemoglobine. De mutatie veroorzaakt een verhoogde afbraak van rode bloedcellen. De ziekte kan worden behandeld met stamcellen uit het beenmerg van een donor.
Stamcellen uit het beenmerg doorlopen verschillende stadia voordat ze als reticulocyten in de bloedbaan komen (afbeelding 1). Vervolgens ontwikkelen ze zich daar in 24 uur tot erytrocyten: rijpe rode bloedcellen.
afbeelding 1: pluripotente stamcel → pro-erytroblast → erytroblast → reticulocyt → erytrocyt$$, 'inline'),
  ('e2a669c4-431a-4cc7-b4b1-c7bf5d315ad3', '8c168e5b-33a0-4aba-b57a-183148ef9ca1', $$stamcellen ontwikkelen zich tot rode bloedcellen$$,
   $$biologie-havo-2023-i-beta-thalassemie-genezen-met-stamceltransplantatie-context3.png$$,
   $$Stamcellen uit het beenmerg ontwikkelen zich tot rode bloedcellen.$$, 'inline'),
  ('27a195f9-002c-4d87-90df-63740da2fd60', '8c168e5b-33a0-4aba-b57a-183148ef9ca1', $$kader: snelle afbraak van rode bloedcellen, verhoogde activiteit beenmerg$$,
   $$biologie-havo-2023-i-beta-thalassemie-genezen-met-stamceltransplantatie-context4.png$$,
   $$Rijpe rode bloedcellen leven gemiddeld drie maanden, maar bij Ryan worden ze al na enkele dagen afgebroken. Om het tekort aan rode bloedcellen gedeeltelijk te compenseren, is de activiteit van het rode beenmerg verhoogd.$$, 'inline'),
  ('2a7f5ab1-88b2-4655-b14a-e6c91659ce6b', '8c168e5b-33a0-4aba-b57a-183148ef9ca1', $$bloedpreparaat: verhouding reticulocyten en rijpe rode bloedcellen$$,
   $$biologie-havo-2023-i-beta-thalassemie-genezen-met-stamceltransplantatie-context5.png$$,
   $$Een medisch laborant maakt een preparaat van een druppel bloed van Ryan en bepaalt met de microscoop de verhouding tussen de reticulocyten en de rijpe rode bloedcellen. In afbeelding 2 zijn twee bloedbeelden te zien, een ervan is dat van Ryan, het andere is een normaal bloedbeeld.$$, 'inline'),
  ('93d7fa35-cb44-4275-baad-6af86e125dc4', '8c168e5b-33a0-4aba-b57a-183148ef9ca1', $$afbeelding 2: bloedbeeld 1 en bloedbeeld 2$$,
   $$biologie-havo-2023-i-beta-thalassemie-genezen-met-stamceltransplantatie-context6.png$$,
   $$afbeelding 2: microscoopfoto''s van twee bloedbeelden: bloedbeeld 1 en bloedbeeld 2$$, 'inline'),
  ('2e06c19c-e0c4-4a8e-952b-3263f3b3aa1e', '8c168e5b-33a0-4aba-b57a-183148ef9ca1', $$verhoogde hartslagfrequentie door tekort aan rode bloedcellen$$,
   $$biologie-havo-2023-i-beta-thalassemie-genezen-met-stamceltransplantatie-context7.png$$,
   $$Door het tekort aan rode bloedcellen in zijn bloed heeft Ryan een verhoogde hartslagfrequentie.$$, 'inline'),
  ('de812722-1d2f-46e9-8337-cedce8049306', '8c168e5b-33a0-4aba-b57a-183148ef9ca1', $$hormoon dat het beenmerg activeert$$,
   $$biologie-havo-2023-i-beta-thalassemie-genezen-met-stamceltransplantatie-context8.png$$,
   $$De verhoogde activiteit van het beenmerg wordt veroorzaakt door een verhoogde afgifte van een bepaald hormoon.$$, 'inline'),
  ('6e135f5c-4ac6-40a5-8b7d-a308917d44c0', '8c168e5b-33a0-4aba-b57a-183148ef9ca1', $$bloedtransfusie via een infuus in de arm$$,
   $$biologie-havo-2023-i-beta-thalassemie-genezen-met-stamceltransplantatie-context9.png$$,
   $$Ryan krijgt elke drie weken een bloedtransfusie via een infuus in een bloedvat in zijn arm. Afbeelding 3 is een schematische tekening van de bloedsomloop.$$, 'inline'),
  ('7f51cfa7-8c37-4fd5-b4c5-70ac613eac76', '8c168e5b-33a0-4aba-b57a-183148ef9ca1', $$afbeelding 3: schema van de bloedsomloop met P, Q, R en S$$,
   $$biologie-havo-2023-i-beta-thalassemie-genezen-met-stamceltransplantatie-context10.png$$,
   $$afbeelding 3: schematische tekening van de bloedsomloop met hart, longen en organen; vier bloedvaten zijn aangegeven met de letters P, Q, R en S$$, 'inline'),
  ('04eeac20-8b04-4388-af41-ef763c6a54cd', '8c168e5b-33a0-4aba-b57a-183148ef9ca1', $$twee typen stamceltransplantatie$$,
   $$biologie-havo-2023-i-beta-thalassemie-genezen-met-stamceltransplantatie-context11.png$$,
   $$Er is geen medicijn voor bèta-thalassemie. Alleen een stamceltransplantatie kan Ryan genezen. Er bestaan twee typen stamceltransplantaties: één waarbij stamcellen van de patiënt zelf gebruikt worden, en één waarbij stamcellen afkomstig zijn van een donor.$$, 'inline'),
  ('6e0349bf-8b35-4ced-9b18-7f10d93b1d4d', '8c168e5b-33a0-4aba-b57a-183148ef9ca1', $$kader: HLA-eiwitten en immuunreactie na stamceltransplantatie$$,
   $$biologie-havo-2023-i-beta-thalassemie-genezen-met-stamceltransplantatie-context12.png$$,
   $$Bij een stamceltransplantatie voor een bèta-thalassemiepatiënt worden de stamcellen van de patiënt gedood en vervangen door stamcellen van een donor. Een deel van deze stamcellen zal zich ontwikkelen tot rode bloedcellen, een ander deel tot afweercellen. Het is belangrijk dat bepaalde membraaneiwitten (HLA-eiwitten) van de donorcellen zo veel mogelijk overeenkomen met die van de patiënt om een immuunreactie te voorkómen. Deze immuunreactie ontstaat als de gedoneerde stamcellen die zich tot afweercellen hebben ontwikkeld, de HLA-eiwitten van de patiënt als lichaamsvreemd herkennen.$$, 'inline'),
  ('058102e6-93c2-4d58-b270-a76463a3552c', '8c168e5b-33a0-4aba-b57a-183148ef9ca1', $$drie uitspraken over de immuunreactie$$,
   $$biologie-havo-2023-i-beta-thalassemie-genezen-met-stamceltransplantatie-context13.png$$,
   $$Over de immuunreactie die kan optreden na de stamceltransplantatie worden de volgende uitspraken gedaan:
1 Bij de immuunreactie zijn de HLA-eiwitten de antigenen.
2 Bij de immuunreactie worden cellen van gezonde weefsels van de patiënt aangevallen.
3 De immuunreactie wordt veroorzaakt doordat de donorstamcellen als lichaamsvreemd worden herkend.$$, 'inline'),
  ('e3a5955f-7f52-4cd8-9480-84373653f027', '8c168e5b-33a0-4aba-b57a-183148ef9ca1', $$kader: autosomaal recessieve overerving; ouders zijn drager$$,
   $$biologie-havo-2023-i-beta-thalassemie-genezen-met-stamceltransplantatie-context14.png$$,
   $$Bèta-thalassemie erft autosomaal recessief over. Ryans ouders zijn beiden drager van het gemuteerde gen, maar hebben geen verschijnselen van bèta-thalassemie.$$, 'inline'),
  ('f374933b-e4c8-4a33-8d6d-f9cbc6688684', '8c168e5b-33a0-4aba-b57a-183148ef9ca1', $$vijf lichaamscellen P-T met één chromosomenpaar$$,
   $$biologie-havo-2023-i-beta-thalassemie-genezen-met-stamceltransplantatie-context15.png$$,
   $$In afbeelding 4 zijn vijf lichaamscellen (P, Q, R, S en T) schematisch afgebeeld. In elke cel is slechts één chromosomenpaar getekend. Het gemuteerde hemoglobine-gen is met zwart aangegeven.$$, 'inline'),
  ('cc6507c5-f49f-4010-a99b-9727c13ddff0', '8c168e5b-33a0-4aba-b57a-183148ef9ca1', $$afbeelding 4: lichaamscellen P, Q, R, S en T$$,
   $$biologie-havo-2023-i-beta-thalassemie-genezen-met-stamceltransplantatie-context16.png$$,
   $$afbeelding 4: vijf lichaamscellen P, Q, R, S en T, elk met één chromosomenpaar; het gemuteerde hemoglobine-gen is zwart aangegeven$$, 'inline'),
  ('9a7266c4-e069-4580-a48b-79b7cdbd6677', '8c168e5b-33a0-4aba-b57a-183148ef9ca1', $$zus Noa is mogelijk drager$$,
   $$biologie-havo-2023-i-beta-thalassemie-genezen-met-stamceltransplantatie-context17.png$$,
   $$Ryans zus Noa heeft geen bèta-thalassemie, maar ze is mogelijk wel drager van de ziekte.$$, 'inline'),
  ('dc3cd6b1-54c7-4ace-85d1-23d07aad61f7', '8c168e5b-33a0-4aba-b57a-183148ef9ca1', $$Noa als donor; verloop van de transplantatie$$,
   $$biologie-havo-2023-i-beta-thalassemie-genezen-met-stamceltransplantatie-context18.png$$,
   $$Het DNA van Noa wordt onderzocht. Ze blijkt geschikt als donor. De kinderarts bespreekt met de ouders van Ryan en Noa het verloop van de stamceltransplantatie en de mogelijke risico’s. In de dagen voorafgaand aan de stamceltransplantatie krijgt Ryan stoffen toegediend waarmee zijn eigen beenmergstamcellen worden gedood. Daarna krijgt Ryan de stamcellen van Noa toegediend. Pas na enkele weken zal blijken of de gedoneerde stamcellen zich ontwikkelen tot nieuwe bloedcellen.$$, 'inline'),
  ('cf64c4d7-4dc1-4e15-aab7-7d18a5f41643', '8c168e5b-33a0-4aba-b57a-183148ef9ca1', $$vier risico's van de stamceltransplantatie$$,
   $$biologie-havo-2023-i-beta-thalassemie-genezen-met-stamceltransplantatie-context19.png$$,
   $$Risico’s voor Ryan bij deze stamceltransplantatie zijn:
1 Er ontstaat een immuunreactie.
2 De gedoneerde stamcellen vermenigvuldigen zich niet.
3 Er is tijdelijk onvoldoende afweer tegen infecties.
4 Er is tijdelijk een verhoogde kans op bloedingen.$$, 'inline'),
  ('b15be8ac-f63f-42db-ab4f-463f5d57044a', '8c168e5b-33a0-4aba-b57a-183148ef9ca1', $$vier mogelijke behandelingen P-S$$,
   $$biologie-havo-2023-i-beta-thalassemie-genezen-met-stamceltransplantatie-context20.png$$,
   $$Om deze risico''s te ondervangen of de gevolgen ervan tegen te gaan, zijn de volgende behandelingen mogelijk:
P een transfusie met bloedplaatjes
Q medicijnen toedienen die de afweer onderdrukken
R vooraf antibiotica toedienen
S vooraf beenmerg van Ryan afnemen en invriezen$$, 'inline'),
  ('dd80c50f-9f02-45c1-a47d-ca6a3c91712e', 'e927b46c-d036-44d7-bbfa-a23eee48d961', $$inleiding: stage op een prehistorische paardenboerderij$$,
   $$biologie-havo-2023-i-mens-temde-het-paard-al-in-de-oertijd-context1.png$$,
   $$Aya volgt de opleiding archeologie aan de hogeschool Saxion. Ze loopt stage in Kazachstan op een vindplaats van een prehistorische paardenboerderij. Daar wordt onderzocht wanneer de mens voor het eerst wilde paarden ging temmen.$$, 'inline'),
  ('0af8c904-7dce-43c6-84b3-df9febf87c12', 'e927b46c-d036-44d7-bbfa-a23eee48d961', $$kader: datering met de C14-methode; drie voorwerpen$$,
   $$biologie-havo-2023-i-mens-temde-het-paard-al-in-de-oertijd-context2.png$$,
   $$Aya selecteert voorwerpen om met behulp van de C14-methode te dateren. Bij deze methode wordt in het laboratorium de ouderdom bepaald aan de hand van de relatieve hoeveelheid radioactieve koolstof- isotopen die aanwezig zijn in organische stoffen. Uit de datering blijkt dat de paardenboerderij er rond 3500 voor Christus moet hebben gestaan. Drie voorwerpen zijn:
− een paardenbot
− een houten kom
− een stenen gebruiksvoorwerp$$, 'inline'),
  ('44c150ee-5a2f-4bd7-9697-420968c405a6', 'e927b46c-d036-44d7-bbfa-a23eee48d961', $$melkzuur in houten kommen uit lactose$$,
   $$biologie-havo-2023-i-mens-temde-het-paard-al-in-de-oertijd-context3.png$$,
   $$De paarden werden waarschijnlijk gemolken; dit werd afgeleid uit de vondst van melkzuur in de resten van houten kommen. Het melkzuur ontstond toen de lactose uit de paardenmelk werd omgezet tijdens een bepaald stofwisselingsproces.$$, 'inline'),
  ('0b08204d-becf-4f60-855a-2669dd8c6d08', 'e927b46c-d036-44d7-bbfa-a23eee48d961', $$kader: DNA-analyse van tamme paardenrassen; kleine variatie in Y-chromosomen$$,
   $$biologie-havo-2023-i-mens-temde-het-paard-al-in-de-oertijd-context4.png$$,
   $$Uit DNA-analyse blijkt dat alle huidige tamme paardenrassen (Equus ferus caballus) afstammen van 17 verschillende familiegroepen wilde paarden. De genetische variatie in het DNA van de Y-chromosomen van tamme paarden blijkt klein te zijn. Bij paarden wordt het geslacht op dezelfde manier door de chromosomen bepaald als bij mensen.$$, 'inline'),
  ('d84c3d62-ea63-41b4-9272-a3752a44b32d', 'e927b46c-d036-44d7-bbfa-a23eee48d961', $$genetische variatie Y-chromosomen afgenomen door fokken$$,
   $$biologie-havo-2023-i-mens-temde-het-paard-al-in-de-oertijd-context5.png$$,
   $$Aya leest dat de genetische variatie van de Y-chromosomen bij tamme paarden is afgenomen als gevolg van fokken (kruisen).$$, 'inline'),
  ('682374fe-ad47-4bed-a1c1-7d52d1e3201c', 'e927b46c-d036-44d7-bbfa-a23eee48d961', $$przewalskipaarden; drie uitspraken over populatie, soort en genus$$,
   $$biologie-havo-2023-i-mens-temde-het-paard-al-in-de-oertijd-context6.png$$,
   $$Tegenwoordig komen wilde paarden nog steeds voor. Dit zijn przewalskipaarden (Equus ferus przewalskii), die te vinden zijn in een nationaal park in Mongolië, in enkele dierentuinen, en in een aantal natuurgebieden. Drie uitspraken over de huidige przewalskipaarden en de huidige tamme paarden zijn:
1 Ze behoren tot dezelfde populatie.
2 Ze behoren tot dezelfde soort.
3 Ze behoren tot hetzelfde genus (geslacht).$$, 'inline'),
  ('f98deb46-0bde-415b-8b50-0000bff3a6d6', 'e927b46c-d036-44d7-bbfa-a23eee48d961', $$evolutionaire stamboom van paardenrassen en de ezel$$,
   $$biologie-havo-2023-i-mens-temde-het-paard-al-in-de-oertijd-context7.png$$,
   $$Aya vindt op internet een evolutionaire stamboom van verschillende paardenrassen en de ezel (afbeelding 1).$$, 'inline'),
  ('34f0016d-4658-4cab-b8d8-e4126437f5aa', 'e927b46c-d036-44d7-bbfa-a23eee48d961', $$afbeelding 1: evolutionaire stamboom$$,
   $$biologie-havo-2023-i-mens-temde-het-paard-al-in-de-oertijd-context8.png$$,
   $$afbeelding 1: evolutionaire stamboom van de ezel en de paardenrassen przewalskipaard, fjord, ijslander, Mongools paard, freiberger, Belgisch trekpaard, standardbred, Franse draver, Amerikaanse draver, arabier en andalusiër$$, 'inline'),
  ('35562fcb-e3b3-4cd4-8e87-2a2ea6430f59', 'e927b46c-d036-44d7-bbfa-a23eee48d961', $$drie uitspraken over de stamboom$$,
   $$biologie-havo-2023-i-mens-temde-het-paard-al-in-de-oertijd-context9.png$$,
   $$Aya doet de volgende uitspraken over deze stamboom:
1 De ezel is de voorouder van alle weergegeven paardenrassen.
2 Het przewalskipaard is van alle weergegeven paardenrassen het meest verwant aan de ezel.
3 De Franse draver is van alle weergegeven paardenrassen het meest verwant aan de Amerikaanse draver.$$, 'inline'),
  ('c24d7de0-ba83-4b0b-a7f7-3a7d51a97ec0', '50724007-6c5e-49f3-a26a-3860aedafd1c', $$inleiding: kan een achtbaanrit nierstenen helpen uitplassen?$$,
   $$biologie-havo-2023-i-nierstenen-in-de-bocht-context1.png$$,
   $$De vader van Sem heeft last van nierstenen. Daarom zoekt Sem naar informatie over het voorkómen en behandelen ervan. Hierbij komt hij een artikel tegen van Amerikaanse wetenschappers die onderzochten of een ritje in de achtbaan helpt om nierstenen uit te plassen.$$, 'inline'),
  ('28d277ae-7bd5-47d6-bece-653b93a2006c', '50724007-6c5e-49f3-a26a-3860aedafd1c', $$kader: ontstaan van nierstenen (afbeelding 1)$$,
   $$biologie-havo-2023-i-nierstenen-in-de-bocht-context2.png$$,
   $$Nierstenen (afbeelding 1) ontstaan wanneer calciumzouten in de urine slecht oplossen en vervolgens kristallen vormen die steeds groter worden. Kleine nierstenen worden gewoon uitgeplast, maar grotere kunnen vast blijven zitten.
afbeelding 1: foto van nierstenen naast een liniaal$$, 'inline'),
  ('6a093890-bd5d-4ac4-8178-ecc7905788ff', '50724007-6c5e-49f3-a26a-3860aedafd1c', $$uitscheiding van calcium-ionen; zes delen van het uitscheidingsstelsel$$,
   $$biologie-havo-2023-i-nierstenen-in-de-bocht-context3.png$$,
   $$Calcium-ionen worden via de nieren uitgescheiden. Een aantal delen van het uitscheidingsstelsel die door een calcium-ion gepasseerd worden zijn:
1 blaas
2 glomerulus
3 nierbuisje
4 urinebuis
5 urineleider
6 verzamelbuisje$$, 'inline'),
  ('b6d1be80-6445-480a-a5cb-c9c917c4a933', '50724007-6c5e-49f3-a26a-3860aedafd1c', $$kader: siliconen niermodel in de achtbaan (afbeelding 2)$$,
   $$biologie-havo-2023-i-nierstenen-in-de-bocht-context4.png$$,
   $$De Amerikaanse wetenschappers maakten een siliconen model van de nier van iemand met nierstenen (afbeelding 2). In dit model werden nierstenen op die posities geplaatst die overeenkomen met de plaatsen waar ze zaten in de echte nier (aangegeven met zwarte stippen). Hierna werd het model gevuld met urine en vervolgens verpakt in een rugzak. De rugzak werd rechtop vastgezet op een stoel van een achtbaan-wagentje. Na een ritje werd gecontroleerd waar de nierstenen zich bevonden. Nierstenen die zich in het reservoir onder in het model bevonden, werden beschouwd als uitgeplast.
afbeelding 2: foto van het siliconen niermodel met de plaatsen P en Q en de posities hoog, midden en laag, en onderaan het reservoir$$, 'inline'),
  ('2794a5a5-c3ee-433e-aefd-3fa81a49f9e4', '50724007-6c5e-49f3-a26a-3860aedafd1c', $$kader: resultaten van het experiment (tabel 1)$$,
   $$biologie-havo-2023-i-nierstenen-in-de-bocht-context5.png$$,
   $$In tabel 1 staan de resultaten van het experiment. Aangegeven is hoeveel van het aantal geteste nierstenen na een rit in de achtbaan in het opvangreservoir terecht zijn gekomen (''uitgeplast''). Er zijn verschillende formaten nierstenen getest.
tabel 1: aantal uitgeplaste / aantal geteste nierstenen, per positie en grootte van de nierstenen (5 mm³ | 14 mm³ | 65 mm³ | totaal)
hoog: 4 / 5 | 4 / 5 | 6 / 11 | 67%
midden: 3 / 7 | 2 / 6 | 1 / 2 | 40%
laag: 2 / 8 | 2 / 9 | 3 / 7 | 29%
totaal: 45% | 40% | 50% | 45%$$, 'inline'),
  ('24404eba-d396-4ef8-8fbf-71d755c43128', '50724007-6c5e-49f3-a26a-3860aedafd1c', $$twee uitspraken over de resultaten$$,
   $$biologie-havo-2023-i-nierstenen-in-de-bocht-context6.png$$,
   $$Over de resultaten van het onderzoek worden de volgende uitspraken gedaan:
1 Hoe groter een niersteen, hoe kleiner de kans dat hij wordt uitgeplast.
2 Hoe hoger een niersteen zich bevindt, hoe groter de kans dat hij wordt uitgeplast.$$, 'inline');

