   $$biologie-havo-2023-i-een-bos-om-op-te-eten-vraag5.png$$, $$1p 5 Verklaar waardoor een monocultuur gevoelig is voor plagen.$$, array['03544714-c186-4a68-b0b9-f0399fe7ae07', '1997bd12-f83a-45aa-89e3-b9b3d15ec86b', '7705085c-4998-4763-9817-dc1739f3f0d4', '7fb51db2-177e-4ebf-ab49-3c591ca0e589']::uuid[]),
