   $$biologie-havo-2023-i-spoedkeizersnede-vraag16.png$$, $$1p 16 Beredeneer dat buikademhaling een te hoge druk op de baarmoeder kan veroorzaken.$$, array['d0724408-f211-43aa-9668-ba898f316e56']::uuid[]),
  ('9f7725ce-5c6a-4645-a1ef-c56fb29efbd4', 'a65f396c-9aea-4a58-b2ee-fc655bbae7c2', 17,
